    /**
     * Tests getting all TrainingRuns.
     *
     * @return    Collection
     */
    public List<TrainingRun> testGetAll() throws Throwable {
    LOGGER.info( "TrainingRunTest:testGetAll() - Retrieving Collection of TrainingRuns:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all TrainingRun : " );
    List<TrainingRun> collection  = null;

    try {
        // call the static get method on the TrainingRunService
        collection = service.getAllTrainingRun();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            TrainingRun currEntity  = null;
            Iterator<TrainingRun> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getTrainingRunId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

